@mcp.tool()
def seo_bulk_create_posts(
    posts: list = None,
) -> dict:
    """Create multiple SEO-optimized posts at once from an array of post data"""
    wp = _wp()
    results = []
    for post in (posts or []):
        body = post if isinstance(post, dict) else {"title": str(post)}
        try:
            results.append(wp.post("/wp/v2/posts", json=body))
        except Exception as exc:
            results.append({"error": str(exc)})
    return {"created": results, "count": len(results)}

