@mcp.tool()
def seo_create_content_cluster(
    pillar_title: str = None,
    pillar_content: str = None,
    pillar_keyword: str = None,
    cluster_posts: list = None,
    category_id: int = None,
) -> dict:
    """Create a content cluster: pillar page + multiple supporting blog posts, all cross-linked"""
    wp = _wp()
    results = {}
    if pillar_title:
        pillar_body = {"title": pillar_title, "status": "draft"}
        if pillar_content: pillar_body["content"] = pillar_content
        if category_id: pillar_body["categories"] = [category_id]
        results["pillar"] = wp.post("/wp/v2/posts", json=pillar_body)
    results["cluster"] = []
    for post in (cluster_posts or []):
        body = post if isinstance(post, dict) else {"title": str(post)}
        if category_id and "categories" not in body: body["categories"] = [category_id]
        try:
            results["cluster"].append(wp.post("/wp/v2/posts", json=body))
        except Exception as exc:
            results["cluster"].append({"error": str(exc)})
    return results

